-- Data only (user decision 2026-10-17). Replaces the mock job roles with the four ServiceNow roles
-- and loads their default flash cards and interview questions from "Flash cards.pdf": each role's
-- own 10 cards, then the 10 ServiceNow fundamentals and 10 HR/behavioural cards every role shares.
-- Every card has an approved interview question linked to it, with a rubric built from the card's
-- keywords; roles ask them in random order. Roles stay draft for an admin to review and approve.
--
-- Safe on any database, and a no-op where the content already exists:
-- - the old mock roles are deleted only when no session used them, and archived otherwise;
-- - a ServiceNow role is inserted only if its slug is free;
-- - cards and questions are added only to a role that has no flash cards yet.
-- Content is attributed to the first active super admin, or left unattributed on a new database.

UPDATE "job_roles" SET "status" = 'archived', "updated_at" = now()
WHERE "slug" IN ('junior-data-analyst', 'sales-development-rep', 'customer-support-associate')
  AND "status" <> 'archived'
  AND EXISTS (SELECT 1 FROM "sessions" s WHERE s."job_role_id" = "job_roles"."id");

DELETE FROM "job_roles"
WHERE "slug" IN ('junior-data-analyst', 'sales-development-rep', 'customer-support-associate')
  AND NOT EXISTS (SELECT 1 FROM "sessions" s WHERE s."job_role_id" = "job_roles"."id");

-- ServiceNow Sales & Order Management
DO $$
DECLARE
  admin_id uuid := (SELECT "id" FROM "users" WHERE "role" = 'super_admin' AND "status" = 'active' AND "deleted_at" IS NULL ORDER BY "created_at" LIMIT 1);
  role_id uuid;
  card_id uuid;
BEGIN
  INSERT INTO "job_roles" ("id", "slug", "title", "blurb", "description_html", "seniority", "key_skills", "status", "settings", "updated_by", "updated_at")
  VALUES (gen_random_uuid(), 'servicenow-sales-order-management', 'ServiceNow Sales & Order Management', 'Configure ServiceNow to run quoting, ordering and fulfilment.', '<p>Builds and supports the ServiceNow Sales and Order Management applications, from product catalogue and quotes through order capture, decomposition and fulfilment.</p><ul><li>Configure the product catalogue, offers and pricing</li><li>Set up order capture, decomposition and fulfilment flows</li><li>Integrate orders with CRM, billing and inventory systems</li><li>Work with sales and operations teams on requirements</li></ul>', 'mid', ARRAY['Sales and Order Management', 'Product catalogue', 'Order decomposition', 'Flow Designer', 'Integrations'], 'draft', '{"questionsPerSession":5,"questionOrder":"random","answerGuideSeconds":120,"requireAllCards":true,"maxSessionsPerCandidate":5,"sessionWeights":{"firstTry":20,"secondTry":55,"learning":25},"dimensionWeights":{"content":45,"structure":20,"delivery":20,"relevance":15}}'::jsonb, admin_id, now())
  ON CONFLICT ("slug") DO NOTHING;

  SELECT "id" INTO role_id FROM "job_roles" WHERE "slug" = 'servicenow-sales-order-management';
  IF EXISTS (SELECT 1 FROM "flash_cards" WHERE "job_role_id" = role_id) THEN
    RETURN;
  END IF;

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 1, 'role_knowledge', 'What is ServiceNow Sales & Order Management?', ARRAY['Quote-to-cash', 'CSM', 'Product catalog', 'Order orchestration'], 'It''s a CSM / Industry app that runs the full quote-to-cash flow: product catalog, quoting, order capture, order orchestration and fulfillment, all on one platform.', ARRAY['Describing it as the service catalog', 'Leaving out fulfillment'], 'Frame it as quote-to-cash on one platform, then list the stages.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is ServiceNow Sales and Order Management?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Quote-to-cash","example":""},{"id":"kp2","point":"CSM","example":""},{"id":"kp3","point":"Product catalog","example":""},{"id":"kp4","point":"Order orchestration","example":""}],"redFlags":["Confuses SOM with the ITSM service catalog"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 2, 'role_knowledge', 'Walk through the order lifecycle end to end.', ARRAY['Capture', 'Validate', 'Decompose', 'Fulfill', 'Close'], 'Customer order is captured, validated, decomposed into order lines and fulfillment tasks, fulfilled by teams or systems, then inventory is updated and the order is closed.', ARRAY['Skipping decomposition', 'Ending at fulfillment without closure'], 'Say the five stages in order: capture, validate, decompose, fulfill, close.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'Walk me through the order lifecycle, end to end.', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Capture","example":""},{"id":"kp2","point":"Validate","example":""},{"id":"kp3","point":"Decompose","example":""},{"id":"kp4","point":"Fulfill","example":""},{"id":"kp5","point":"Close","example":""}],"redFlags":["Stages out of order or missing decomposition"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 3, 'role_knowledge', 'What is order decomposition?', ARRAY['Product offering', 'Product spec', 'Service/resource spec', 'Decomposition rules'], 'Breaking a commercial product offering into technical service and resource specifications, which generate the order line items and fulfillment tasks.', ARRAY['Confusing decomposition with splitting a bill', 'Not mentioning specifications'], 'Move from commercial to technical: offering, then spec, then tasks.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is order decomposition?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Product offering","example":""},{"id":"kp2","point":"Product spec","example":""},{"id":"kp3","point":"Service/resource spec","example":""},{"id":"kp4","point":"Decomposition rules","example":""}],"redFlags":["Cannot link decomposition to fulfillment tasks"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 4, 'role_knowledge', 'Product Offering vs Product Specification?', ARRAY['Commercial vs technical', 'Product model', 'Characteristics'], 'An offering is what the customer buys (price, bundle, terms). A specification is the technical definition of what is delivered. One spec can sit behind many offerings.', ARRAY['Treating them as the same thing', 'Reversing which one is customer-facing'], 'Use "commercial vs technical" and an example of one spec behind two offerings.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between a product offering and a product specification?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Commercial vs technical","example":""},{"id":"kp2","point":"Product model","example":""},{"id":"kp3","point":"Characteristics","example":""}],"redFlags":["Says the specification holds the price"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 5, 'role_knowledge', 'What is a fulfillment task?', ARRAY['Order task', 'Assignment group', 'Dependency', 'External system'], 'A unit of work created from decomposition, such as provisioning or shipping, assigned to a fulfillment team or an external system. The order completes when all its tasks close.', ARRAY['Forgetting tasks can go to external systems', 'Ignoring dependencies between tasks'], 'End with the rule: the order completes when all its tasks close.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a fulfillment task?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Order task","example":""},{"id":"kp2","point":"Assignment group","example":""},{"id":"kp3","point":"Dependency","example":""},{"id":"kp4","point":"External system","example":""}],"redFlags":["Cannot say where fulfillment tasks come from"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 6, 'situational', 'An order is stuck. Where do you look first?', ARRAY['Order tasks', 'Open state', 'Flow execution', 'Integration log', 'Escalate'], 'Open the order''s lines and tasks, filter for open ones, then check the blocking task''s assignee, work notes, flow context and integration logs.', ARRAY['Restarting the order without diagnosis', 'Not checking the flow context'], 'Give an order of checks: tasks first, then the flow, then integrations.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'An order is stuck and not progressing. Where do you look first?', 'situational', 'medium', '{"keyPoints":[{"id":"kp1","point":"Order tasks","example":""},{"id":"kp2","point":"Open state","example":""},{"id":"kp3","point":"Flow execution","example":""},{"id":"kp4","point":"Integration log","example":""},{"id":"kp5","point":"Escalate","example":""}],"redFlags":["Cancels or recreates the order before finding the cause"],"expectedStructure":"problem_solution"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 7, 'role_knowledge', 'How are SLAs applied to orders?', ARRAY['Task SLA', 'Start/pause/stop', 'Breach', 'Notifications'], 'SLA definitions on the order or task table start, pause and stop on conditions. Task SLA records track time left and fire notifications at 50/75/100%.', ARRAY['Thinking SLAs are only for incidents', 'Forgetting pause conditions'], 'Mention start, pause and stop conditions and the 50/75/100% alerts.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How are SLAs applied to orders?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Task SLA","example":""},{"id":"kp2","point":"Start/pause/stop","example":""},{"id":"kp3","point":"Breach","example":""},{"id":"kp4","point":"Notifications","example":""}],"redFlags":["Cannot explain how an SLA starts or stops"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 8, 'situational', 'How do you prioritize orders close to breach?', ARRAY['SLA % elapsed', 'Business impact', 'Customer tier', 'Dashboard'], 'Sort by SLA time left and percentage elapsed, then weigh customer tier, order value and blocking dependencies. Escalate the at-risk ones.', ARRAY['First come, first served', 'Ignoring customer tier and value'], 'Combine SLA time left with business impact, not time alone.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How do you prioritize orders that are close to breaching their SLA?', 'situational', 'medium', '{"keyPoints":[{"id":"kp1","point":"SLA % elapsed","example":""},{"id":"kp2","point":"Business impact","example":""},{"id":"kp3","point":"Customer tier","example":""},{"id":"kp4","point":"Dashboard","example":""}],"redFlags":["Works orders only in arrival order"],"expectedStructure":"problem_solution"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 9, 'role_knowledge', 'What is a change order (order amendment)?', ARRAY['Amend', 'Cancel', 'In-flight order', 'Revision'], 'A request to modify or cancel an in-flight order. The system compares the changes, then adjusts or cancels the affected lines and tasks.', ARRAY['Confusing it with an ITSM change request', 'Saying the whole order is recreated'], 'Stress "in-flight": the order is already being fulfilled.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a change order, or order amendment?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Amend","example":""},{"id":"kp2","point":"Cancel","example":""},{"id":"kp3","point":"In-flight order","example":""},{"id":"kp4","point":"Revision","example":""}],"redFlags":["Confuses an order amendment with an ITSM change request"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 10, 'role_knowledge', 'How do orders enter SOM from outside?', ARRAY['TM Forum Open API', 'REST', 'CPQ/CRM', 'Workspace'], 'Through the TM Forum Open APIs (such as Product Order API), REST integrations from CRM or CPQ tools, or the agent workspace and portal.', ARRAY['Only mentioning manual entry', 'Not knowing the TM Forum APIs'], 'Name the TM Forum Product Order API and one manual channel.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How do orders enter Sales and Order Management from outside systems?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"TM Forum Open API","example":""},{"id":"kp2","point":"REST","example":""},{"id":"kp3","point":"CPQ/CRM","example":""},{"id":"kp4","point":"Workspace","example":""}],"redFlags":["Cannot name any integration channel"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 11, 'role_knowledge', 'What is ServiceNow?', ARRAY['Cloud', 'SaaS', 'Workflow automation', 'Single data model', 'Now Platform'], 'A cloud-based platform for automating digital workflows. ITSM is its core product, alongside HR, CSM, ITOM and custom apps, all on one data model.', ARRAY['Calling it only a ticketing tool', 'Listing products without saying what ties them together'], 'Lead with "workflow automation on one platform", then name two or three products.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'In your own words, what is ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Cloud","example":""},{"id":"kp2","point":"SaaS","example":""},{"id":"kp3","point":"Workflow automation","example":""},{"id":"kp4","point":"Single data model","example":""},{"id":"kp5","point":"Now Platform","example":""}],"redFlags":["Describes ServiceNow as only an IT helpdesk tool"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 12, 'role_knowledge', 'What is an instance?', ARRAY['Dev/test/prod', 'URL', 'Sub-production', 'Clone'], 'Your company''s own copy of ServiceNow, with its own URL and database. Most companies have dev, test and production instances.', ARRAY['Confusing an instance with a user account or licence', 'Forgetting sub-production instances exist'], 'Mention the dev, test and production chain and how changes move along it.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a ServiceNow instance?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Dev/test/prod","example":""},{"id":"kp2","point":"URL","example":""},{"id":"kp3","point":"Sub-production","example":""},{"id":"kp4","point":"Clone","example":""}],"redFlags":["Suggests making changes directly in production"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 13, 'role_knowledge', 'What is an update set?', ARRAY['Capture changes', 'Retrieve', 'Preview', 'Commit', 'Collisions'], 'A container that records configuration changes in one instance so you can move them to another. You complete it, retrieve it, preview it, then commit.', ARRAY['Thinking update sets capture data records by default', 'Skipping the preview step and its collisions'], 'Say the four steps in order: complete, retrieve, preview, commit.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is an update set, and how do you move one between instances?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Capture changes","example":""},{"id":"kp2","point":"Retrieve","example":""},{"id":"kp3","point":"Preview","example":""},{"id":"kp4","point":"Commit","example":""},{"id":"kp5","point":"Collisions","example":""}],"redFlags":["Commits without previewing or resolving collisions"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 14, 'role_knowledge', 'What is the Task table?', ARRAY['Parent table', 'Extends', 'Inheritance', 'Shared fields'], 'A base table that Incident, Problem, Change and Request extend. They share fields like number, state, assignment group and short description.', ARRAY['Treating Task as a table of to-do items', 'Not knowing which tables extend it'], 'Name two tables that extend Task and one field they inherit from it.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is the Task table, and why does it matter?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Parent table","example":""},{"id":"kp2","point":"Extends","example":""},{"id":"kp3","point":"Inheritance","example":""},{"id":"kp4","point":"Shared fields","example":""}],"redFlags":["Cannot name any table that extends Task"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 15, 'role_knowledge', 'What is a reference field?', ARRAY['sys_id', 'Foreign key', 'Dot-walking'], 'A field that points to a record on another table, such as caller_id pointing to sys_user. It stores the sys_id.', ARRAY['Saying it stores the display value instead of the sys_id', 'Confusing it with a choice field'], 'Use caller_id pointing to sys_user as your example.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a reference field in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"sys_id","example":""},{"id":"kp2","point":"Foreign key","example":""},{"id":"kp3","point":"Dot-walking","example":""}],"redFlags":["Says a reference field stores the display name"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 16, 'role_knowledge', 'What is a sys_id?', ARRAY['Unique ID', '32-char GUID', 'Primary key'], 'A unique 32-character ID that every record has. Scripts use it to find a record reliably.', ARRAY['Confusing the sys_id with the record number like INC0010001', 'Hard-coding sys_ids without explaining the risk'], 'Say "32-character unique ID" and why scripts prefer it to names or numbers.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a sys_id, and how is it used?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Unique ID","example":""},{"id":"kp2","point":"32-char GUID","example":""},{"id":"kp3","point":"Primary key","example":""}],"redFlags":["Confuses the sys_id with the record number"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 17, 'role_knowledge', 'What is dot-walking?', ARRAY['Reference chain', 'Related fields', 'No extra query'], 'Reaching fields on referenced records using dots, such as caller_id.department.name. It works in scripts, lists, conditions and reports.', ARRAY['Thinking it only works in scripts', 'Not linking it to reference fields'], 'Give a chained example like caller_id.department.name.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
