-- ServiceNow ITSM / Platform Developer
DO $$
DECLARE
  admin_id uuid := (SELECT "id" FROM "users" WHERE "role" = 'super_admin' AND "status" = 'active' AND "deleted_at" IS NULL ORDER BY "created_at" LIMIT 1);
  role_id uuid;
  card_id uuid;
BEGIN
  INSERT INTO "job_roles" ("id", "slug", "title", "blurb", "description_html", "seniority", "key_skills", "status", "settings", "updated_by", "updated_at")
  VALUES (gen_random_uuid(), 'servicenow-itsm-platform-developer', 'ServiceNow ITSM / Platform Developer', 'Build and extend ITSM processes on the ServiceNow platform.', '<p>Develops on the ServiceNow platform to deliver and improve ITSM processes such as incident, problem, change and request management.</p><ul><li>Build business rules, client scripts and UI policies</li><li>Automate workflows with Flow Designer and IntegrationHub</li><li>Configure incident, problem, change and request processes</li><li>Follow upgrade-safe development practices</li></ul>', 'mid', ARRAY['ITSM processes', 'JavaScript (Glide API)', 'Business rules and client scripts', 'Flow Designer', 'REST integrations'], 'draft', '{"questionsPerSession":5,"questionOrder":"random","answerGuideSeconds":120,"requireAllCards":true,"maxSessionsPerCandidate":5,"sessionWeights":{"firstTry":20,"secondTry":55,"learning":25},"dimensionWeights":{"content":45,"structure":20,"delivery":20,"relevance":15}}'::jsonb, admin_id, now())
  ON CONFLICT ("slug") DO NOTHING;

  SELECT "id" INTO role_id FROM "job_roles" WHERE "slug" = 'servicenow-itsm-platform-developer';
  IF EXISTS (SELECT 1 FROM "flash_cards" WHERE "job_role_id" = role_id) THEN
    RETURN;
  END IF;

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 1, 'role_knowledge', 'What is a business rule?', ARRAY['Server-side', 'When to run', 'Condition', 'current/previous'], 'Server-side script that runs when a record is displayed, inserted, updated, deleted or queried. Types are before, after, async and display.', ARRAY['Saying business rules run in the browser', 'Missing the async type'], 'Name the four types: before, after, async, display.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a business rule?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Server-side","example":""},{"id":"kp2","point":"When to run","example":""},{"id":"kp3","point":"Condition","example":""},{"id":"kp4","point":"current/previous","example":""}],"redFlags":["Says business rules are client-side"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 2, 'role_knowledge', 'Before vs after business rule?', ARRAY['Pre-save', 'Post-save', 'No current.update()', 'Related records'], 'Before runs prior to the database save and changes the current record without update(). After runs post-save and is used to update related records.', ARRAY['Calling current.update() in a before rule', 'Using after rules to change the current record'], 'Mention never calling current.update() in a before rule.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between a before and an after business rule?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Pre-save","example":""},{"id":"kp2","point":"Post-save","example":""},{"id":"kp3","point":"No current.update()","example":""},{"id":"kp4","point":"Related records","example":""}],"redFlags":["Recommends current.update() inside a business rule"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 3, 'role_knowledge', 'After vs async business rule?', ARRAY['Same transaction', 'Scheduled job', 'Performance', 'No user message'], 'After is synchronous in the same transaction, so the user waits. Async is queued as a background job, which is faster for the user but runs later.', ARRAY['Thinking async rules can show messages to the user', 'Using after rules for slow integrations'], 'Tie the choice to user wait time and integrations.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between an after and an async business rule?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Same transaction","example":""},{"id":"kp2","point":"Scheduled job","example":""},{"id":"kp3","point":"Performance","example":""},{"id":"kp4","point":"No user message","example":""}],"redFlags":["Cannot say when async is the better choice"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 4, 'role_knowledge', 'What is a display business rule used for?', ARRAY['g_scratchpad', 'Form load', 'Client access'], 'Runs when the form loads and passes server data to client scripts through g_scratchpad. This avoids extra server calls.', ARRAY['Using it to change data on save', 'Not knowing about g_scratchpad'], 'Say g_scratchpad and why it saves a server call.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a display business rule used for?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"g_scratchpad","example":""},{"id":"kp2","point":"Form load","example":""},{"id":"kp3","point":"Client access","example":""}],"redFlags":["Cannot explain g_scratchpad"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 5, 'role_knowledge', 'What is an ACL?', ARRAY['Access control', 'Role', 'Condition', 'Script', 'table.field', 'Security Debugger'], 'Access Control rule that decides who can read, write, create or delete a table or field, using roles, conditions and scripts. Table rules are checked before field rules.', ARRAY['Thinking UI policies secure data', 'Ignoring table versus field order'], 'Mention table rules checked before field rules, and the Security Debugger.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is an ACL, and how is it evaluated?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Access control","example":""},{"id":"kp2","point":"Role","example":""},{"id":"kp3","point":"Condition","example":""},{"id":"kp4","point":"Script","example":""},{"id":"kp5","point":"table.field","example":""},{"id":"kp6","point":"Security Debugger","example":""}],"redFlags":["Says hiding a field on the form secures it"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

