  VALUES (gen_random_uuid(), role_id, 6, 'role_knowledge', 'What is Flow Designer?', ARRAY['Trigger', 'Action', 'Subflow', 'Data pill', 'Low-code'], 'Low-code automation tool with triggers, conditions, actions and subflows. It replaces most legacy workflows and scripted automation.', ARRAY['Saying legacy workflow is still the default choice', 'Not knowing subflows'], 'Name the building blocks: trigger, actions, subflows, data pills.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
