  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 7, 'role_knowledge', 'What triggers can a flow have?', ARRAY['Record', 'Scheduled', 'Application', 'Service catalog'], 'Record triggers (created or updated), scheduled triggers (daily, weekly, once) and application triggers (inbound email, service catalog, SLA).', ARRAY['Only mentioning record triggers', 'Forgetting service catalog triggers'], 'Group them into three: record, scheduled, application.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
