  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 8, 'role_knowledge', 'What is a custom action?', ARRAY['Inputs', 'Outputs', 'Script step', 'Reusable', 'Spoke'], 'A reusable Flow Designer step with defined inputs, steps and outputs, built once and used in many flows. You can package them in a spoke.', ARRAY['Confusing actions with subflows', 'Not mentioning inputs and outputs'], 'Stress reuse: inputs and outputs, built once, packaged in a spoke.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a custom action in Flow Designer?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Inputs","example":""},{"id":"kp2","point":"Outputs","example":""},{"id":"kp3","point":"Script step","example":""},{"id":"kp4","point":"Reusable","example":""},{"id":"kp5","point":"Spoke","example":""}],"redFlags":["Cannot say why you would build a custom action"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 9, 'role_knowledge', 'Synchronous vs asynchronous?', ARRAY['Blocking', 'Callback', 'getXMLAnswer', 'Background'], 'Sync waits for the result before continuing, while async continues and handles the result later. Example: GlideAjax getXMLAnswer is async, getXMLWait is sync.', ARRAY['Recommending synchronous calls on the client', 'Not knowing what a callback is'], 'Use the GlideAjax example: getXMLAnswer versus getXMLWait.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between synchronous and asynchronous calls in ServiceNow?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Blocking","example":""},{"id":"kp2","point":"Callback","example":""},{"id":"kp3","point":"getXMLAnswer","example":""},{"id":"kp4","point":"Background","example":""}],"redFlags":["Recommends getXMLWait as the normal choice"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 10, 'role_knowledge', 'What is OAuth 2.0 in ServiceNow?', ARRAY['Access token', 'Refresh token', 'Client ID/secret', 'Application Registry', 'Grant type'], 'A token-based authentication method for integrations. You configure an Application Registry entry and an OAuth profile, and the access token replaces a password.', ARRAY['Confusing OAuth with basic authentication', 'Not knowing about refresh tokens'], 'Mention the Application Registry and why tokens beat stored passwords.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How is OAuth 2.0 used in ServiceNow integrations?', 'role_knowledge', 'hard', '{"keyPoints":[{"id":"kp1","point":"Access token","example":""},{"id":"kp2","point":"Refresh token","example":""},{"id":"kp3","point":"Client ID/secret","example":""},{"id":"kp4","point":"Application Registry","example":""},{"id":"kp5","point":"Grant type","example":""}],"redFlags":["Suggests sharing a user password for integrations"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 11, 'role_knowledge', 'What is ServiceNow?', ARRAY['Cloud', 'SaaS', 'Workflow automation', 'Single data model', 'Now Platform'], 'A cloud-based platform for automating digital workflows. ITSM is its core product, alongside HR, CSM, ITOM and custom apps, all on one data model.', ARRAY['Calling it only a ticketing tool', 'Listing products without saying what ties them together'], 'Lead with "workflow automation on one platform", then name two or three products.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'In your own words, what is ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Cloud","example":""},{"id":"kp2","point":"SaaS","example":""},{"id":"kp3","point":"Workflow automation","example":""},{"id":"kp4","point":"Single data model","example":""},{"id":"kp5","point":"Now Platform","example":""}],"redFlags":["Describes ServiceNow as only an IT helpdesk tool"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 12, 'role_knowledge', 'What is an instance?', ARRAY['Dev/test/prod', 'URL', 'Sub-production', 'Clone'], 'Your company''s own copy of ServiceNow, with its own URL and database. Most companies have dev, test and production instances.', ARRAY['Confusing an instance with a user account or licence', 'Forgetting sub-production instances exist'], 'Mention the dev, test and production chain and how changes move along it.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a ServiceNow instance?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Dev/test/prod","example":""},{"id":"kp2","point":"URL","example":""},{"id":"kp3","point":"Sub-production","example":""},{"id":"kp4","point":"Clone","example":""}],"redFlags":["Suggests making changes directly in production"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 13, 'role_knowledge', 'What is an update set?', ARRAY['Capture changes', 'Retrieve', 'Preview', 'Commit', 'Collisions'], 'A container that records configuration changes in one instance so you can move them to another. You complete it, retrieve it, preview it, then commit.', ARRAY['Thinking update sets capture data records by default', 'Skipping the preview step and its collisions'], 'Say the four steps in order: complete, retrieve, preview, commit.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is an update set, and how do you move one between instances?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Capture changes","example":""},{"id":"kp2","point":"Retrieve","example":""},{"id":"kp3","point":"Preview","example":""},{"id":"kp4","point":"Commit","example":""},{"id":"kp5","point":"Collisions","example":""}],"redFlags":["Commits without previewing or resolving collisions"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 14, 'role_knowledge', 'What is the Task table?', ARRAY['Parent table', 'Extends', 'Inheritance', 'Shared fields'], 'A base table that Incident, Problem, Change and Request extend. They share fields like number, state, assignment group and short description.', ARRAY['Treating Task as a table of to-do items', 'Not knowing which tables extend it'], 'Name two tables that extend Task and one field they inherit from it.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is the Task table, and why does it matter?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Parent table","example":""},{"id":"kp2","point":"Extends","example":""},{"id":"kp3","point":"Inheritance","example":""},{"id":"kp4","point":"Shared fields","example":""}],"redFlags":["Cannot name any table that extends Task"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 15, 'role_knowledge', 'What is a reference field?', ARRAY['sys_id', 'Foreign key', 'Dot-walking'], 'A field that points to a record on another table, such as caller_id pointing to sys_user. It stores the sys_id.', ARRAY['Saying it stores the display value instead of the sys_id', 'Confusing it with a choice field'], 'Use caller_id pointing to sys_user as your example.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a reference field in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"sys_id","example":""},{"id":"kp2","point":"Foreign key","example":""},{"id":"kp3","point":"Dot-walking","example":""}],"redFlags":["Says a reference field stores the display name"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 16, 'role_knowledge', 'What is a sys_id?', ARRAY['Unique ID', '32-char GUID', 'Primary key'], 'A unique 32-character ID that every record has. Scripts use it to find a record reliably.', ARRAY['Confusing the sys_id with the record number like INC0010001', 'Hard-coding sys_ids without explaining the risk'], 'Say "32-character unique ID" and why scripts prefer it to names or numbers.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a sys_id, and how is it used?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Unique ID","example":""},{"id":"kp2","point":"32-char GUID","example":""},{"id":"kp3","point":"Primary key","example":""}],"redFlags":["Confuses the sys_id with the record number"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 17, 'role_knowledge', 'What is dot-walking?', ARRAY['Reference chain', 'Related fields', 'No extra query'], 'Reaching fields on referenced records using dots, such as caller_id.department.name. It works in scripts, lists, conditions and reports.', ARRAY['Thinking it only works in scripts', 'Not linking it to reference fields'], 'Give a chained example like caller_id.department.name.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
