  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 18, 'role_knowledge', 'Roles vs groups vs users?', ARRAY['itil', 'admin', 'Group membership', 'Assignment', 'Least privilege'], 'Users are people. Groups are teams that get work assigned. Roles grant permissions. Best practice is to give roles to groups, not individuals.', ARRAY['Mixing up groups and roles', 'Assigning roles directly to users as standard practice'], 'Finish with the best practice: assign roles to groups, not individual users.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between roles, groups and users in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"itil","example":""},{"id":"kp2","point":"admin","example":""},{"id":"kp3","point":"Group membership","example":""},{"id":"kp4","point":"Assignment","example":""},{"id":"kp5","point":"Least privilege","example":""}],"redFlags":["Recommends giving admin to users to fix access issues"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 19, 'role_knowledge', 'Client-side vs server-side scripting?', ARRAY['Browser', 'Instance', 'g_form', 'GlideRecord', 'GlideAjax bridge'], 'Client-side runs in the browser (client scripts, UI policies, g_form). Server-side runs on the instance (business rules, Script Includes, GlideRecord).', ARRAY['Using GlideRecord in client scripts', 'Not knowing where business rules run'], 'Name one API on each side, then GlideAjax as the bridge between them.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between client-side and server-side scripting in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Browser","example":""},{"id":"kp2","point":"Instance","example":""},{"id":"kp3","point":"g_form","example":""},{"id":"kp4","point":"GlideRecord","example":""},{"id":"kp5","point":"GlideAjax bridge","example":""}],"redFlags":["Says business rules run in the browser"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 20, 'role_knowledge', 'What are the ServiceNow release names?', ARRAY['Biannual', 'Alphabetical cities', 'Upgrade', 'Family release'], 'Releases are named alphabetically after cities, twice a year, with one supported upgrade path. Recent ones include Xanadu, Yokohama, Zurich and Australia.', ARRAY['Not knowing the current release', 'Thinking releases come out every month'], 'Name the release you work on now and the next one.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
