  VALUES (gen_random_uuid(), role_id, 21, 'motivation', 'Tell me about yourself.', ARRAY['60 seconds', 'Current role', 'One result', 'Why this role'], 'Present, past, future in 60 seconds: your current role and modules, one past project with a result, and why this role fits next.', ARRAY['Reciting your whole CV', 'Ending without saying why this role fits'], 'Keep it to 60 seconds: present, past, future.', 'approved', admin_id, admin_id, now(), now())
