  VALUES (gen_random_uuid(), role_id, 25, 'behavioural', 'Describe a difficult issue you solved.', ARRAY['STAR', 'Root cause', 'Logs', 'Result'], 'Use STAR: the situation, your task, the debugging steps you took (logs, debugger, impersonation), and the result with a number.', ARRAY['No clear root cause', 'Skipping the result'], 'Spend most of the time on the steps you took, not the background.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'Describe a difficult issue you solved.', 'behavioural', 'medium', '{"keyPoints":[{"id":"kp1","point":"STAR","example":""},{"id":"kp2","point":"Root cause","example":""},{"id":"kp3","point":"Logs","example":""},{"id":"kp4","point":"Result","example":""}],"redFlags":["Blames others for the issue","Fixes symptoms with no root cause"],"expectedStructure":"star"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 26, 'situational', 'How do you handle a requirement you disagree with?', ARRAY['OOTB first', 'Trade-offs', 'Stakeholder', 'Document decision'], 'Understand the business need, suggest an out-of-the-box or lower-risk option with the trade-offs, and then go with the agreed decision and document it.', ARRAY['Refusing to build it', 'Building it silently without raising the risk'], 'Show you push back with options, then commit to the decision.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How do you handle a requirement you disagree with?', 'situational', 'medium', '{"keyPoints":[{"id":"kp1","point":"OOTB first","example":""},{"id":"kp2","point":"Trade-offs","example":""},{"id":"kp3","point":"Stakeholder","example":""},{"id":"kp4","point":"Document decision","example":""}],"redFlags":["Refuses to follow the agreed decision"],"expectedStructure":"problem_solution"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 27, 'role_knowledge', 'How do you deploy changes between instances?', ARRAY['Update set', 'Dev-test-prod', 'Approval', 'Change window', 'Rollback'], 'Use update sets or the application repository/source control, test in dev and test, get approval, then commit to production in a change window.', ARRAY['Skipping testing in a sub-production instance', 'No rollback plan'], 'Walk through dev, test, approval and production, and mention rollback.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How do you deploy changes between instances?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Update set","example":""},{"id":"kp2","point":"Dev-test-prod","example":""},{"id":"kp3","point":"Approval","example":""},{"id":"kp4","point":"Change window","example":""},{"id":"kp5","point":"Rollback","example":""}],"redFlags":["Suggests changing production directly"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 28, 'motivation', 'How do you keep your skills current?', ARRAY['PDI', 'Release notes', 'Now Learning', 'Community'], 'Read release notes for each family release, use a Personal Developer Instance (PDI), take Now Learning courses, and join the Community.', ARRAY['A vague "I read online"', 'Not knowing about Personal Developer Instances'], 'Mention one thing you learned recently from your PDI or release notes.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
