  VALUES (gen_random_uuid(), role_id, card_id, 'How do you keep your ServiceNow skills current?', 'motivation', 'easy', '{"keyPoints":[{"id":"kp1","point":"PDI","example":""},{"id":"kp2","point":"Release notes","example":""},{"id":"kp3","point":"Now Learning","example":""},{"id":"kp4","point":"Community","example":""}],"redFlags":["Gives no concrete learning habit"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 29, 'behavioural', 'How do you work in an Agile team?', ARRAY['Sprint', 'User story', 'Acceptance criteria', 'Stand-up', 'Demo'], 'Two-week sprints, stand-ups, user stories with acceptance criteria, estimation, and demos at sprint review. Mention ServiceNow Agile/SAFe if used.', ARRAY['Reciting Agile definitions only', 'No mention of acceptance criteria'], 'Describe your part in a real sprint, not Agile theory.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How do you work in an Agile team?', 'behavioural', 'easy', '{"keyPoints":[{"id":"kp1","point":"Sprint","example":""},{"id":"kp2","point":"User story","example":""},{"id":"kp3","point":"Acceptance criteria","example":""},{"id":"kp4","point":"Stand-up","example":""},{"id":"kp5","point":"Demo","example":""}],"redFlags":["Cannot describe their part in a sprint"],"expectedStructure":"star"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 30, 'motivation', 'Do you have any questions for us?', ARRAY['Roadmap', 'Team', 'Upgrade cycle', 'First 90 days'], 'Always ask one or two: the team''s main modules and roadmap, how releases and upgrades are handled, or what success looks like in the first 90 days.', ARRAY['Saying you have no questions', 'Only asking about salary or leave'], 'Always have two questions ready; never say "no questions".', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
