-- ServiceNow Custom Apps Developer
DO $$
DECLARE
  admin_id uuid := (SELECT "id" FROM "users" WHERE "role" = 'super_admin' AND "status" = 'active' AND "deleted_at" IS NULL ORDER BY "created_at" LIMIT 1);
  role_id uuid;
  card_id uuid;
BEGIN
  INSERT INTO "job_roles" ("id", "slug", "title", "blurb", "description_html", "seniority", "key_skills", "status", "settings", "updated_by", "updated_at")
  VALUES (gen_random_uuid(), 'servicenow-custom-apps-developer', 'ServiceNow Custom Apps Developer', 'Design and build scoped custom applications on ServiceNow.', '<p>Designs and builds scoped custom applications on the ServiceNow platform, from data model and security through user interface and integrations.</p><ul><li>Design tables, relationships and access controls for new apps</li><li>Build user experiences with UI Builder and Service Portal</li><li>Write server-side and client-side logic in scoped apps</li><li>Ship apps through update sets or source control</li></ul>', 'mid', ARRAY['Scoped applications', 'Data modelling', 'Access control (ACLs)', 'UI Builder and Service Portal', 'JavaScript (Glide API)'], 'draft', '{"questionsPerSession":5,"questionOrder":"random","answerGuideSeconds":120,"requireAllCards":true,"maxSessionsPerCandidate":5,"sessionWeights":{"firstTry":20,"secondTry":55,"learning":25},"dimensionWeights":{"content":45,"structure":20,"delivery":20,"relevance":15}}'::jsonb, admin_id, now())
  ON CONFLICT ("slug") DO NOTHING;

  SELECT "id" INTO role_id FROM "job_roles" WHERE "slug" = 'servicenow-custom-apps-developer';
  IF EXISTS (SELECT 1 FROM "flash_cards" WHERE "job_role_id" = role_id) THEN
    RETURN;
  END IF;

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 1, 'role_knowledge', 'What is a scoped application?', ARRAY['Scope', 'Namespace', 'Isolation', 'App Engine Studio', 'Cross-scope'], 'An app built in its own namespace (x_vendor_app), so its tables, scripts and permissions are isolated from global and other apps.', ARRAY['Building new apps in global by default', 'Not knowing about cross-scope privileges'], 'Mention the x_ namespace prefix and cross-scope access.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a scoped application?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Scope","example":""},{"id":"kp2","point":"Namespace","example":""},{"id":"kp3","point":"Isolation","example":""},{"id":"kp4","point":"App Engine Studio","example":""},{"id":"kp5","point":"Cross-scope","example":""}],"redFlags":["Says scope has no effect on access"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 2, 'role_knowledge', 'What is a Script Include?', ARRAY['Reusable', 'Server-side', 'Class', 'Client callable'], 'A reusable server-side class or function library, called from business rules, flows or the client through GlideAjax.', ARRAY['Thinking Script Includes run in the browser', 'Forgetting the client callable flag'], 'Say where you call one from: business rules, flows and GlideAjax.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a Script Include?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Reusable","example":""},{"id":"kp2","point":"Server-side","example":""},{"id":"kp3","point":"Class","example":""},{"id":"kp4","point":"Client callable","example":""}],"redFlags":["Duplicates the same code across business rules instead"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 3, 'role_knowledge', 'What is GlideAjax?', ARRAY['AbstractAjaxProcessor', 'sysparm_name', 'getXMLAnswer', 'Callback'], 'It lets a client script call a client-callable Script Include asynchronously and return only the data it needs.', ARRAY['Using GlideRecord in a client script instead', 'Using getXMLWait by default'], 'Walk the chain: client script, GlideAjax, Script Include, callback.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is GlideAjax, and when do you use it?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"AbstractAjaxProcessor","example":""},{"id":"kp2","point":"sysparm_name","example":""},{"id":"kp3","point":"getXMLAnswer","example":""},{"id":"kp4","point":"Callback","example":""}],"redFlags":["Suggests GlideRecord in client scripts"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 4, 'role_knowledge', 'What is GlideRecord?', ARRAY['addQuery', 'query()', 'next()', 'insert()', 'update()'], 'The server-side API to query, insert, update and delete records in a table.', ARRAY['Forgetting to call query() before next()', 'Running GlideRecord in client scripts'], 'Say the basic pattern out loud: addQuery, query, while next.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is GlideRecord?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"addQuery","example":""},{"id":"kp2","point":"query()","example":""},{"id":"kp3","point":"next()","example":""},{"id":"kp4","point":"insert()","example":""},{"id":"kp5","point":"update()","example":""}],"redFlags":["Cannot describe a basic GlideRecord query"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 5, 'role_knowledge', 'Client script types?', ARRAY['onLoad', 'onChange', 'onSubmit', 'onCellEdit', 'g_form'], 'onLoad, onChange, onSubmit and onCellEdit. They run in the browser and use g_form and g_user.', ARRAY['Forgetting onCellEdit', 'Thinking client scripts run on the server'], 'Name all four and give one use for onChange.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What types of client scripts are there?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"onLoad","example":""},{"id":"kp2","point":"onChange","example":""},{"id":"kp3","point":"onSubmit","example":""},{"id":"kp4","point":"onCellEdit","example":""},{"id":"kp5","point":"g_form","example":""}],"redFlags":["Cannot name the client script types"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 6, 'role_knowledge', 'UI policy vs client script?', ARRAY['No-code', 'Mandatory/visible/read-only', 'Conditions', 'Best practice'], 'UI policies make fields mandatory, read-only or visible without code. Client scripts are for logic that a UI policy can''t express. Prefer UI policies.', ARRAY['Writing client scripts for simple mandatory fields', 'Thinking UI policies secure data'], 'State the best practice: UI policy first, client script only when needed.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'When do you use a UI policy instead of a client script?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"No-code","example":""},{"id":"kp2","point":"Mandatory/visible/read-only","example":""},{"id":"kp3","point":"Conditions","example":""},{"id":"kp4","point":"Best practice","example":""}],"redFlags":["Prefers code for everything a UI policy can do"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 7, 'role_knowledge', 'What is a transform map?', ARRAY['Import set', 'Field map', 'Coalesce', 'Transform script'], 'It maps fields from an import set staging table to a target table. Coalesce fields stop duplicates by updating existing records.', ARRAY['Not knowing what coalesce does', 'Loading straight into the target table'], 'Explain coalesce: match an existing record and update it instead of inserting.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a transform map?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Import set","example":""},{"id":"kp2","point":"Field map","example":""},{"id":"kp3","point":"Coalesce","example":""},{"id":"kp4","point":"Transform script","example":""}],"redFlags":["Cannot explain how duplicates are prevented on import"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 8, 'situational', 'How do you avoid duplicate incidents?', ARRAY['correlation_id', 'Coalesce', 'Before BR', 'setAbortAction'], 'Store the external ID in a correlation field, coalesce on it during import, and check for an open match in a before-insert business rule.', ARRAY['Deleting duplicates afterwards instead of preventing them', 'Matching on short description'], 'Mention correlation_id, then a before-insert check as the safety net.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'Incidents from an external system are arriving as duplicates. How do you prevent that?', 'situational', 'medium', '{"keyPoints":[{"id":"kp1","point":"correlation_id","example":""},{"id":"kp2","point":"Coalesce","example":""},{"id":"kp3","point":"Before BR","example":""},{"id":"kp4","point":"setAbortAction","example":""}],"redFlags":["Proposes cleaning duplicates manually as the fix"],"expectedStructure":"problem_solution"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 9, 'situational', 'How do you avoid duplicate CIs?', ARRAY['IRE', 'Identification rule', 'Reconciliation', 'CMDBTransformUtil'], 'Load CIs through IRE (Identification and Reconciliation Engine), which matches them on identification rules like serial number before inserting.', ARRAY['Inserting CIs directly with GlideRecord', 'Matching on CI name only'], 'Say IRE, and that it matches on rules such as serial number before inserting.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How do you stop duplicate configuration items being created when loading CI data?', 'situational', 'medium', '{"keyPoints":[{"id":"kp1","point":"IRE","example":""},{"id":"kp2","point":"Identification rule","example":""},{"id":"kp3","point":"Reconciliation","example":""},{"id":"kp4","point":"CMDBTransformUtil","example":""}],"redFlags":["Bypasses IRE when loading CIs"],"expectedStructure":"problem_solution"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 10, 'role_knowledge', 'What is a catalog item vs a record producer?', ARRAY['Variables', 'RITM', 'Record producer', 'Target table', 'Flow'], 'A catalog item creates a request (REQ, RITM, tasks). A record producer uses a catalog form to create a record on another table, such as an Incident.', ARRAY['Thinking a record producer creates an RITM', 'Not mentioning variables'], 'Contrast what each creates: a REQ and RITM versus a record on a target table.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between a catalog item and a record producer?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Variables","example":""},{"id":"kp2","point":"RITM","example":""},{"id":"kp3","point":"Record producer","example":""},{"id":"kp4","point":"Target table","example":""},{"id":"kp5","point":"Flow","example":""}],"redFlags":["Cannot say what a record producer creates"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 11, 'role_knowledge', 'What is ServiceNow?', ARRAY['Cloud', 'SaaS', 'Workflow automation', 'Single data model', 'Now Platform'], 'A cloud-based platform for automating digital workflows. ITSM is its core product, alongside HR, CSM, ITOM and custom apps, all on one data model.', ARRAY['Calling it only a ticketing tool', 'Listing products without saying what ties them together'], 'Lead with "workflow automation on one platform", then name two or three products.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'In your own words, what is ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Cloud","example":""},{"id":"kp2","point":"SaaS","example":""},{"id":"kp3","point":"Workflow automation","example":""},{"id":"kp4","point":"Single data model","example":""},{"id":"kp5","point":"Now Platform","example":""}],"redFlags":["Describes ServiceNow as only an IT helpdesk tool"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 12, 'role_knowledge', 'What is an instance?', ARRAY['Dev/test/prod', 'URL', 'Sub-production', 'Clone'], 'Your company''s own copy of ServiceNow, with its own URL and database. Most companies have dev, test and production instances.', ARRAY['Confusing an instance with a user account or licence', 'Forgetting sub-production instances exist'], 'Mention the dev, test and production chain and how changes move along it.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a ServiceNow instance?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Dev/test/prod","example":""},{"id":"kp2","point":"URL","example":""},{"id":"kp3","point":"Sub-production","example":""},{"id":"kp4","point":"Clone","example":""}],"redFlags":["Suggests making changes directly in production"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 13, 'role_knowledge', 'What is an update set?', ARRAY['Capture changes', 'Retrieve', 'Preview', 'Commit', 'Collisions'], 'A container that records configuration changes in one instance so you can move them to another. You complete it, retrieve it, preview it, then commit.', ARRAY['Thinking update sets capture data records by default', 'Skipping the preview step and its collisions'], 'Say the four steps in order: complete, retrieve, preview, commit.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is an update set, and how do you move one between instances?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Capture changes","example":""},{"id":"kp2","point":"Retrieve","example":""},{"id":"kp3","point":"Preview","example":""},{"id":"kp4","point":"Commit","example":""},{"id":"kp5","point":"Collisions","example":""}],"redFlags":["Commits without previewing or resolving collisions"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 14, 'role_knowledge', 'What is the Task table?', ARRAY['Parent table', 'Extends', 'Inheritance', 'Shared fields'], 'A base table that Incident, Problem, Change and Request extend. They share fields like number, state, assignment group and short description.', ARRAY['Treating Task as a table of to-do items', 'Not knowing which tables extend it'], 'Name two tables that extend Task and one field they inherit from it.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is the Task table, and why does it matter?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Parent table","example":""},{"id":"kp2","point":"Extends","example":""},{"id":"kp3","point":"Inheritance","example":""},{"id":"kp4","point":"Shared fields","example":""}],"redFlags":["Cannot name any table that extends Task"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 15, 'role_knowledge', 'What is a reference field?', ARRAY['sys_id', 'Foreign key', 'Dot-walking'], 'A field that points to a record on another table, such as caller_id pointing to sys_user. It stores the sys_id.', ARRAY['Saying it stores the display value instead of the sys_id', 'Confusing it with a choice field'], 'Use caller_id pointing to sys_user as your example.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a reference field in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"sys_id","example":""},{"id":"kp2","point":"Foreign key","example":""},{"id":"kp3","point":"Dot-walking","example":""}],"redFlags":["Says a reference field stores the display name"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 16, 'role_knowledge', 'What is a sys_id?', ARRAY['Unique ID', '32-char GUID', 'Primary key'], 'A unique 32-character ID that every record has. Scripts use it to find a record reliably.', ARRAY['Confusing the sys_id with the record number like INC0010001', 'Hard-coding sys_ids without explaining the risk'], 'Say "32-character unique ID" and why scripts prefer it to names or numbers.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a sys_id, and how is it used?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Unique ID","example":""},{"id":"kp2","point":"32-char GUID","example":""},{"id":"kp3","point":"Primary key","example":""}],"redFlags":["Confuses the sys_id with the record number"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 17, 'role_knowledge', 'What is dot-walking?', ARRAY['Reference chain', 'Related fields', 'No extra query'], 'Reaching fields on referenced records using dots, such as caller_id.department.name. It works in scripts, lists, conditions and reports.', ARRAY['Thinking it only works in scripts', 'Not linking it to reference fields'], 'Give a chained example like caller_id.department.name.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is dot-walking, and where can you use it?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Reference chain","example":""},{"id":"kp2","point":"Related fields","example":""},{"id":"kp3","point":"No extra query","example":""}],"redFlags":["Cannot give a dot-walking example"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 18, 'role_knowledge', 'Roles vs groups vs users?', ARRAY['itil', 'admin', 'Group membership', 'Assignment', 'Least privilege'], 'Users are people. Groups are teams that get work assigned. Roles grant permissions. Best practice is to give roles to groups, not individuals.', ARRAY['Mixing up groups and roles', 'Assigning roles directly to users as standard practice'], 'Finish with the best practice: assign roles to groups, not individual users.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between roles, groups and users in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"itil","example":""},{"id":"kp2","point":"admin","example":""},{"id":"kp3","point":"Group membership","example":""},{"id":"kp4","point":"Assignment","example":""},{"id":"kp5","point":"Least privilege","example":""}],"redFlags":["Recommends giving admin to users to fix access issues"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 19, 'role_knowledge', 'Client-side vs server-side scripting?', ARRAY['Browser', 'Instance', 'g_form', 'GlideRecord', 'GlideAjax bridge'], 'Client-side runs in the browser (client scripts, UI policies, g_form). Server-side runs on the instance (business rules, Script Includes, GlideRecord).', ARRAY['Using GlideRecord in client scripts', 'Not knowing where business rules run'], 'Name one API on each side, then GlideAjax as the bridge between them.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between client-side and server-side scripting in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Browser","example":""},{"id":"kp2","point":"Instance","example":""},{"id":"kp3","point":"g_form","example":""},{"id":"kp4","point":"GlideRecord","example":""},{"id":"kp5","point":"GlideAjax bridge","example":""}],"redFlags":["Says business rules run in the browser"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 20, 'role_knowledge', 'What are the ServiceNow release names?', ARRAY['Biannual', 'Alphabetical cities', 'Upgrade', 'Family release'], 'Releases are named alphabetically after cities, twice a year, with one supported upgrade path. Recent ones include Xanadu, Yokohama, Zurich and Australia.', ARRAY['Not knowing the current release', 'Thinking releases come out every month'], 'Name the release you work on now and the next one.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
