  VALUES (gen_random_uuid(), role_id, card_id, 'How are ServiceNow releases named and delivered?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Biannual","example":""},{"id":"kp2","point":"Alphabetical cities","example":""},{"id":"kp3","point":"Upgrade","example":""},{"id":"kp4","point":"Family release","example":""}],"redFlags":["Cannot name any recent release"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 21, 'motivation', 'Tell me about yourself.', ARRAY['60 seconds', 'Current role', 'One result', 'Why this role'], 'Present, past, future in 60 seconds: your current role and modules, one past project with a result, and why this role fits next.', ARRAY['Reciting your whole CV', 'Ending without saying why this role fits'], 'Keep it to 60 seconds: present, past, future.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
