  VALUES (gen_random_uuid(), role_id, 23, 'motivation', 'Why ServiceNow as a career?', ARRAY['Growth', 'Enterprise demand', 'Process + code', 'Certifications'], 'It''s a fast-growing platform used by most large enterprises. You like solving process problems with both configuration and code, and the skills have strong demand.', ARRAY['Only mentioning salary', 'A generic answer that fits any technology'], 'Pair a market reason with a personal one: what you enjoy building.', 'approved', admin_id, admin_id, now(), now())
