  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 25, 'behavioural', 'Describe a difficult issue you solved.', ARRAY['STAR', 'Root cause', 'Logs', 'Result'], 'Use STAR: the situation, your task, the debugging steps you took (logs, debugger, impersonation), and the result with a number.', ARRAY['No clear root cause', 'Skipping the result'], 'Spend most of the time on the steps you took, not the background.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
