  VALUES (gen_random_uuid(), role_id, 28, 'motivation', 'How do you keep your skills current?', ARRAY['PDI', 'Release notes', 'Now Learning', 'Community'], 'Read release notes for each family release, use a Personal Developer Instance (PDI), take Now Learning courses, and join the Community.', ARRAY['A vague "I read online"', 'Not knowing about Personal Developer Instances'], 'Mention one thing you learned recently from your PDI or release notes.', 'approved', admin_id, admin_id, now(), now())
