  UPDATE "job_roles" SET "settings" = '{"questionsPerSession":5,"questionOrder":"random","answerGuideSeconds":120,"requireAllCards":true,"maxSessionsPerCandidate":5,"sessionWeights":{"firstTry":20,"secondTry":55,"learning":25},"dimensionWeights":{"content":45,"structure":20,"delivery":20,"relevance":15}}'::jsonb, "updated_at" = now() WHERE "id" = role_id;
END $$;

-- ServiceNow ITSM / CMDB Administrator
DO $$
DECLARE
  admin_id uuid := (SELECT "id" FROM "users" WHERE "role" = 'super_admin' AND "status" = 'active' AND "deleted_at" IS NULL ORDER BY "created_at" LIMIT 1);
  role_id uuid;
  card_id uuid;
BEGIN
  INSERT INTO "job_roles" ("id", "slug", "title", "blurb", "description_html", "seniority", "key_skills", "status", "settings", "updated_by", "updated_at")
  VALUES (gen_random_uuid(), 'servicenow-itsm-cmdb-administrator', 'ServiceNow ITSM / CMDB Administrator', 'Administer ITSM and keep the CMDB accurate and healthy.', '<p>Administers the ServiceNow ITSM modules and the Configuration Management Database, keeping configuration data complete, accurate and useful.</p><ul><li>Administer users, groups, roles and ITSM configuration</li><li>Maintain CMDB classes, relationships and data quality</li><li>Run discovery and identification and reconciliation rules</li><li>Monitor CMDB health and fix duplicates and stale records</li></ul>', 'mid', ARRAY['CMDB and CSDM', 'Discovery', 'Identification and reconciliation', 'ITSM administration', 'Data quality'], 'draft', '{"questionsPerSession":5,"questionOrder":"random","answerGuideSeconds":120,"requireAllCards":true,"maxSessionsPerCandidate":5,"sessionWeights":{"firstTry":20,"secondTry":55,"learning":25},"dimensionWeights":{"content":45,"structure":20,"delivery":20,"relevance":15}}'::jsonb, admin_id, now())
  ON CONFLICT ("slug") DO NOTHING;

  SELECT "id" INTO role_id FROM "job_roles" WHERE "slug" = 'servicenow-itsm-cmdb-administrator';
  IF EXISTS (SELECT 1 FROM "flash_cards" WHERE "job_role_id" = role_id) THEN
    RETURN;
  END IF;

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 1, 'role_knowledge', 'Incident vs Problem vs Change?', ARRAY['Restore', 'Root cause', 'Planned fix', 'Known error', 'CAB'], 'An incident restores service fast, a problem finds and removes the root cause, and a change makes a controlled, approved modification.', ARRAY['Treating problem and incident as the same', 'Forgetting change approval'], 'One verb each: restore, find the root cause, modify safely.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between an incident, a problem and a change?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Restore","example":""},{"id":"kp2","point":"Root cause","example":""},{"id":"kp3","point":"Planned fix","example":""},{"id":"kp4","point":"Known error","example":""},{"id":"kp5","point":"CAB","example":""}],"redFlags":["Says incidents should wait for the root cause"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 2, 'role_knowledge', 'What are the incident states?', ARRAY['Lifecycle', 'Resolve', 'Close code', 'Auto-close'], 'New, In Progress, On Hold, Resolved, Closed (or Canceled). A resolved incident auto-closes after a set number of days.', ARRAY['Confusing Resolved with Closed', 'Forgetting On Hold'], 'List the states in order and mention auto-close after resolution.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What are the incident states?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Lifecycle","example":""},{"id":"kp2","point":"Resolve","example":""},{"id":"kp3","point":"Close code","example":""},{"id":"kp4","point":"Auto-close","example":""}],"redFlags":["Cannot list the incident states"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 3, 'role_knowledge', 'How is priority calculated?', ARRAY['Impact', 'Urgency', 'Data lookup', 'Priority matrix'], 'Priority comes from Impact × Urgency through the priority data lookup table. Users set impact and urgency, not priority directly.', ARRAY['Saying users choose priority directly', 'Mixing up impact and urgency'], 'Say "impact times urgency" and the data lookup table.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How is incident priority calculated?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Impact","example":""},{"id":"kp2","point":"Urgency","example":""},{"id":"kp3","point":"Data lookup","example":""},{"id":"kp4","point":"Priority matrix","example":""}],"redFlags":["Says priority is set by hand"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 4, 'role_knowledge', 'How do you define an SLA?', ARRAY['SLA Definition', 'Schedule', 'Start/pause/stop', 'Task SLA'], 'Create an SLA Definition with the table, duration, schedule and start, pause and stop conditions. A Task SLA record then tracks each ticket.', ARRAY['Forgetting the schedule', 'Not mentioning pause conditions'], 'List the parts of the definition, then say Task SLA tracks each ticket.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'How do you define an SLA in ServiceNow?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"SLA Definition","example":""},{"id":"kp2","point":"Schedule","example":""},{"id":"kp3","point":"Start/pause/stop","example":""},{"id":"kp4","point":"Task SLA","example":""}],"redFlags":["Cannot describe what an SLA definition contains"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 5, 'situational', 'An SLA isn''t attaching. What do you check?', ARRAY['Active', 'Start condition', 'Schedule', 'Task SLA', 'Repair SLA'], 'Check that the definition is active, the start condition matches the record, and the schedule is valid. Then look for cancelled Task SLAs and logs.', ARRAY['Recreating the SLA definition straight away', 'Not checking the start condition against the record'], 'Check in order: active, start condition, schedule, then logs.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'An SLA isn''t attaching to a ticket. What do you check?', 'situational', 'medium', '{"keyPoints":[{"id":"kp1","point":"Active","example":""},{"id":"kp2","point":"Start condition","example":""},{"id":"kp3","point":"Schedule","example":""},{"id":"kp4","point":"Task SLA","example":""},{"id":"kp5","point":"Repair SLA","example":""}],"redFlags":["Edits the definition before diagnosing"],"expectedStructure":"problem_solution"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 6, 'role_knowledge', 'SLA vs OLA vs UC?', ARRAY['Customer', 'Internal team', 'Vendor', 'Agreement'], 'An SLA is with the customer, an OLA is between internal teams, and an Underpinning Contract (UC) is with an external vendor.', ARRAY['Mixing up OLA and UC', 'Thinking all three are with customers'], 'One word each: customer, internal team, vendor.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between an SLA, an OLA and an underpinning contract?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Customer","example":""},{"id":"kp2","point":"Internal team","example":""},{"id":"kp3","point":"Vendor","example":""},{"id":"kp4","point":"Agreement","example":""}],"redFlags":["Swaps OLA and UC"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 7, 'situational', 'Wrong assignment group on incidents. How do you fix it?', ARRAY['Assignment rules', 'Audit history', 'Order', 'Predictive Intelligence'], 'Check the assignment rules, data lookups and any business rule or flow setting the group. Correct the rule''s conditions and order, then reassign the existing tickets.', ARRAY['Only reassigning tickets by hand', 'Not checking rule order'], 'Find what set the group, using audit history, before changing any rule.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'Incidents are going to the wrong assignment group. How do you fix it?', 'situational', 'medium', '{"keyPoints":[{"id":"kp1","point":"Assignment rules","example":""},{"id":"kp2","point":"Audit history","example":""},{"id":"kp3","point":"Order","example":""},{"id":"kp4","point":"Predictive Intelligence","example":""}],"redFlags":["Fixes the tickets but not the rule"],"expectedStructure":"problem_solution"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 8, 'situational', 'A user can''t see work notes. Why?', ARRAY['itil role', 'ACL', 'Impersonate', 'Security Debugger', 'Additional comments'], 'Work notes need the itil role (or similar) through ACLs. Impersonate the user, then check their roles, the field ACL, the form layout and UI policies.', ARRAY['Granting admin to fix it', 'Confusing work notes with additional comments'], 'Start by impersonating the user, then check roles and the field ACL.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'A user can''t see work notes on an incident. Why might that be?', 'situational', 'medium', '{"keyPoints":[{"id":"kp1","point":"itil role","example":""},{"id":"kp2","point":"ACL","example":""},{"id":"kp3","point":"Impersonate","example":""},{"id":"kp4","point":"Security Debugger","example":""},{"id":"kp5","point":"Additional comments","example":""}],"redFlags":["Grants the admin role to fix visibility"],"expectedStructure":"problem_solution"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 9, 'role_knowledge', 'What is the CMDB and what is IRE?', ARRAY['CI', 'Relationships', 'Identification rules', 'Reconciliation', 'Data source precedence'], 'The CMDB stores configuration items and their relationships. IRE is the engine that identifies and reconciles incoming CI data to stop duplicates.', ARRAY['Describing the CMDB as an asset list', 'Not knowing what IRE does'], 'Mention relationships, not just CIs, and IRE stopping duplicates.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is the CMDB, and what is IRE?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"CI","example":""},{"id":"kp2","point":"Relationships","example":""},{"id":"kp3","point":"Identification rules","example":""},{"id":"kp4","point":"Reconciliation","example":""},{"id":"kp5","point":"Data source precedence","example":""}],"redFlags":["Says CIs should be inserted directly, bypassing IRE"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 10, 'role_knowledge', 'Client script vs catalog client script?', ARRAY['Table form', 'Catalog item', 'Variables', 'Applies on RITM/task'], 'A client script runs on a table form like Incident. A catalog client script runs on a catalog item or variable set and works with variables.', ARRAY['Thinking they are interchangeable', 'Forgetting variable sets'], 'Contrast where each runs: a table form versus a catalog item or variable set.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between a client script and a catalog client script?', 'role_knowledge', 'medium', '{"keyPoints":[{"id":"kp1","point":"Table form","example":""},{"id":"kp2","point":"Catalog item","example":""},{"id":"kp3","point":"Variables","example":""},{"id":"kp4","point":"Applies on RITM/task","example":""}],"redFlags":["Cannot say where a catalog client script runs"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 11, 'role_knowledge', 'What is ServiceNow?', ARRAY['Cloud', 'SaaS', 'Workflow automation', 'Single data model', 'Now Platform'], 'A cloud-based platform for automating digital workflows. ITSM is its core product, alongside HR, CSM, ITOM and custom apps, all on one data model.', ARRAY['Calling it only a ticketing tool', 'Listing products without saying what ties them together'], 'Lead with "workflow automation on one platform", then name two or three products.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'In your own words, what is ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Cloud","example":""},{"id":"kp2","point":"SaaS","example":""},{"id":"kp3","point":"Workflow automation","example":""},{"id":"kp4","point":"Single data model","example":""},{"id":"kp5","point":"Now Platform","example":""}],"redFlags":["Describes ServiceNow as only an IT helpdesk tool"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 12, 'role_knowledge', 'What is an instance?', ARRAY['Dev/test/prod', 'URL', 'Sub-production', 'Clone'], 'Your company''s own copy of ServiceNow, with its own URL and database. Most companies have dev, test and production instances.', ARRAY['Confusing an instance with a user account or licence', 'Forgetting sub-production instances exist'], 'Mention the dev, test and production chain and how changes move along it.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a ServiceNow instance?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Dev/test/prod","example":""},{"id":"kp2","point":"URL","example":""},{"id":"kp3","point":"Sub-production","example":""},{"id":"kp4","point":"Clone","example":""}],"redFlags":["Suggests making changes directly in production"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 13, 'role_knowledge', 'What is an update set?', ARRAY['Capture changes', 'Retrieve', 'Preview', 'Commit', 'Collisions'], 'A container that records configuration changes in one instance so you can move them to another. You complete it, retrieve it, preview it, then commit.', ARRAY['Thinking update sets capture data records by default', 'Skipping the preview step and its collisions'], 'Say the four steps in order: complete, retrieve, preview, commit.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is an update set, and how do you move one between instances?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Capture changes","example":""},{"id":"kp2","point":"Retrieve","example":""},{"id":"kp3","point":"Preview","example":""},{"id":"kp4","point":"Commit","example":""},{"id":"kp5","point":"Collisions","example":""}],"redFlags":["Commits without previewing or resolving collisions"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 14, 'role_knowledge', 'What is the Task table?', ARRAY['Parent table', 'Extends', 'Inheritance', 'Shared fields'], 'A base table that Incident, Problem, Change and Request extend. They share fields like number, state, assignment group and short description.', ARRAY['Treating Task as a table of to-do items', 'Not knowing which tables extend it'], 'Name two tables that extend Task and one field they inherit from it.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is the Task table, and why does it matter?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Parent table","example":""},{"id":"kp2","point":"Extends","example":""},{"id":"kp3","point":"Inheritance","example":""},{"id":"kp4","point":"Shared fields","example":""}],"redFlags":["Cannot name any table that extends Task"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 15, 'role_knowledge', 'What is a reference field?', ARRAY['sys_id', 'Foreign key', 'Dot-walking'], 'A field that points to a record on another table, such as caller_id pointing to sys_user. It stores the sys_id.', ARRAY['Saying it stores the display value instead of the sys_id', 'Confusing it with a choice field'], 'Use caller_id pointing to sys_user as your example.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a reference field in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"sys_id","example":""},{"id":"kp2","point":"Foreign key","example":""},{"id":"kp3","point":"Dot-walking","example":""}],"redFlags":["Says a reference field stores the display name"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 16, 'role_knowledge', 'What is a sys_id?', ARRAY['Unique ID', '32-char GUID', 'Primary key'], 'A unique 32-character ID that every record has. Scripts use it to find a record reliably.', ARRAY['Confusing the sys_id with the record number like INC0010001', 'Hard-coding sys_ids without explaining the risk'], 'Say "32-character unique ID" and why scripts prefer it to names or numbers.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is a sys_id, and how is it used?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Unique ID","example":""},{"id":"kp2","point":"32-char GUID","example":""},{"id":"kp3","point":"Primary key","example":""}],"redFlags":["Confuses the sys_id with the record number"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 17, 'role_knowledge', 'What is dot-walking?', ARRAY['Reference chain', 'Related fields', 'No extra query'], 'Reaching fields on referenced records using dots, such as caller_id.department.name. It works in scripts, lists, conditions and reports.', ARRAY['Thinking it only works in scripts', 'Not linking it to reference fields'], 'Give a chained example like caller_id.department.name.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What is dot-walking, and where can you use it?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"Reference chain","example":""},{"id":"kp2","point":"Related fields","example":""},{"id":"kp3","point":"No extra query","example":""}],"redFlags":["Cannot give a dot-walking example"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 18, 'role_knowledge', 'Roles vs groups vs users?', ARRAY['itil', 'admin', 'Group membership', 'Assignment', 'Least privilege'], 'Users are people. Groups are teams that get work assigned. Roles grant permissions. Best practice is to give roles to groups, not individuals.', ARRAY['Mixing up groups and roles', 'Assigning roles directly to users as standard practice'], 'Finish with the best practice: assign roles to groups, not individual users.', 'approved', admin_id, admin_id, now(), now())
  RETURNING "id" INTO card_id;
  INSERT INTO "questions" ("id", "job_role_id", "flash_card_id", "text", "category", "difficulty", "rubric", "status", "created_by", "updated_at")
  VALUES (gen_random_uuid(), role_id, card_id, 'What''s the difference between roles, groups and users in ServiceNow?', 'role_knowledge', 'easy', '{"keyPoints":[{"id":"kp1","point":"itil","example":""},{"id":"kp2","point":"admin","example":""},{"id":"kp3","point":"Group membership","example":""},{"id":"kp4","point":"Assignment","example":""},{"id":"kp5","point":"Least privilege","example":""}],"redFlags":["Recommends giving admin to users to fix access issues"],"expectedStructure":"free"}'::jsonb, 'approved', admin_id, now());

  INSERT INTO "flash_cards" ("id", "job_role_id", "position", "category", "question", "strong_answer_points", "sample_answer_outline", "common_mistakes", "tip", "status", "created_by", "approved_by", "approved_at", "updated_at")
  VALUES (gen_random_uuid(), role_id, 19, 'role_knowledge', 'Client-side vs server-side scripting?', ARRAY['Browser', 'Instance', 'g_form', 'GlideRecord', 'GlideAjax bridge'], 'Client-side runs in the browser (client scripts, UI policies, g_form). Server-side runs on the instance (business rules, Script Includes, GlideRecord).', ARRAY['Using GlideRecord in client scripts', 'Not knowing where business rules run'], 'Name one API on each side, then GlideAjax as the bridge between them.', 'approved', admin_id, admin_id, now(), now())
