  VALUES (gen_random_uuid(), role_id, 22, 'behavioural', 'What were your roles and responsibilities on your last project?', ARRAY['Client', 'Modules', 'Three tasks', 'Outcome', 'Team size'], 'Name the client and domain, your role, the modules you worked on, three main tasks and one measurable outcome.', ARRAY['Describing what the team did, not what you did', 'No measurable outcome'], 'Say "I", not "we", and end with one number.', 'approved', admin_id, admin_id, now(), now())
