  VALUES (gen_random_uuid(), role_id, 24, 'motivation', 'Which certifications do you have or plan?', ARRAY['CSA', 'CAD', 'CIS-ITSM', 'CIS-CSM', 'Now Learning'], 'Start with CSA (Certified System Administrator), then a CAD (Application Developer) or a CIS (Implementation Specialist) in your module, such as ITSM or CSM.', ARRAY['Listing certifications without a plan', 'Naming certifications unrelated to the role'], 'Name what you hold, what is next, and a rough date for it.', 'approved', admin_id, admin_id, now(), now())
