  VALUES (gen_random_uuid(), role_id, 26, 'situational', 'How do you handle a requirement you disagree with?', ARRAY['OOTB first', 'Trade-offs', 'Stakeholder', 'Document decision'], 'Understand the business need, suggest an out-of-the-box or lower-risk option with the trade-offs, and then go with the agreed decision and document it.', ARRAY['Refusing to build it', 'Building it silently without raising the risk'], 'Show you push back with options, then commit to the decision.', 'approved', admin_id, admin_id, now(), now())
