  VALUES (gen_random_uuid(), role_id, 27, 'role_knowledge', 'How do you deploy changes between instances?', ARRAY['Update set', 'Dev-test-prod', 'Approval', 'Change window', 'Rollback'], 'Use update sets or the application repository/source control, test in dev and test, get approval, then commit to production in a change window.', ARRAY['Skipping testing in a sub-production instance', 'No rollback plan'], 'Walk through dev, test, approval and production, and mention rollback.', 'approved', admin_id, admin_id, now(), now())
