  VALUES (gen_random_uuid(), role_id, 30, 'motivation', 'Do you have any questions for us?', ARRAY['Roadmap', 'Team', 'Upgrade cycle', 'First 90 days'], 'Always ask one or two: the team''s main modules and roadmap, how releases and upgrades are handled, or what success looks like in the first 90 days.', ARRAY['Saying you have no questions', 'Only asking about salary or leave'], 'Always have two questions ready; never say "no questions".', 'approved', admin_id, admin_id, now(), now())
